function [ac,per] = pulseac(nmat,dt);%function ac = pulseac(nmat);if nargin<2    dt=0.01;endwarning offMAXLAG = 1.5;per = dt*(1:(1+floor(MAXLAG/dt)))';ac = zeros(1,floor(MAXLAG/dt)+1);if size(nmat,1)<2 	%disp('empty');	return; endp=conv(brown(nmat,dt),mttbgauss(-0.1:dt:0.1,0,0.1));xp=xcorr(p,p,round(MAXLAG/dt));%xp=xp/sum(xp);i1 = (length(xp)+1)/2;i2 = min(i1 + floor(MAXLAG/dt), length(xp));xp = xp / xp(i1); % normalize zero lag to unity correlation 080305 PTxxp=xp(i1:i2);p = dt*(1:length(xxp))';% apply resonance model of Van Noorden & Moelants%f0=2.193; b=0.5; %f=1./p; a1=(f0*f0-f.*f).^2+b*f.^2; a2=f0^4+f.^4;%w=(1./sqrt(a1))-(1./sqrt(a2));w = max(1 - 0.25*(log2(p/0.5)).^2, 0);ac = xxp(:).*w(:);ac = ac';